parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "customer_name": {
      "type": "string",
      "description": "Full name of the customer, empty if not given"
    },
    "phone": {
      "type": "string",
      "description": "Phone number as written, empty if not given"
    },
    "street": {
      "type": "string",
      "description": "Street and house number of the job site, empty if not given"
    },
    "postcode": {
      "type": "string",
      "description": "Postcode of the job site (5 digits DE, 4 digits AT/CH), empty if not given"
    },
    "city": {
      "type": "string",
      "description": "City of the job site, empty if not given"
    },
    "trade": {
      "type": "string",
      "enum": [
        "Sanitär",
        "Heizung",
        "Klima/Lüftung",
        "Elektro",
        "Sonstiges"
      ],
      "description": "Which trade the request belongs to"
    },
    "request_type": {
      "type": "string",
      "enum": [
        "Notdienst",
        "Reparatur",
        "Wartung",
        "Neuinstallation/Angebot",
        "Sonstiges"
      ]
    },
    "urgency": {
      "type": "string",
      "enum": [
        "emergency",
        "soon",
        "plannable"
      ],
      "description": "emergency = active water leak, no heating or hot water in cold weather, gas smell, flooding; soon = defect without immediate damage; plannable = maintenance, quote, new installation"
    },
    "device_info": {
      "type": "string",
      "description": "Device, manufacturer, model or age if mentioned (e.g. 'Gastherme Vaillant, ca. 15 Jahre'), empty if not given"
    },
    "property_type": {
      "type": "string",
      "enum": [
        "Einfamilienhaus",
        "Wohnung",
        "Mehrfamilienhaus",
        "Gewerbe",
        "unbekannt"
      ]
    },
    "preferred_dates": {
      "type": "string",
      "description": "Preferred dates or times mentioned by the customer, empty if none"
    },
    "summary": {
      "type": "string",
      "description": "Summary of the request in German, at most two sentences, factual"
    }
  },
  "required": [
    "trade",
    "request_type",
    "urgency",
    "summary"
  ]
}

parameters.jsCode:
// Combines the AI result with the original email and decides what is missing.
const settings = $('Settings').first().json;
const mail = $('New inquiry email').first().json;
const ai = $input.first().json.output ?? $input.first().json;

const fromRaw = String(mail.from ?? '');
const senderEmail = (fromRaw.match(/<([^>]+)>/)?.[1] ?? fromRaw).trim();

// Service area: list of postcode prefixes from Settings, e.g. "40, 41, 42"
const prefixes = String(settings.serviceAreaPostcodePrefixes || '')
  .split(',').map(p => p.trim()).filter(Boolean);
const postcode = String(ai.postcode || '').trim();
let inServiceArea = 'unbekannt';
if (postcode && prefixes.length) {
  inServiceArea = prefixes.some(p => postcode.startsWith(p)) ? 'ja' : 'nein';
}

// What we need before someone can call back or plan the job
const missing = [];
if (!String(ai.phone || '').trim()) missing.push('Telefonnummer für den Rückruf');
if (!postcode || !String(ai.street || '').trim()) missing.push('Adresse des Einsatzorts (Straße, Hausnummer, PLZ)');
if (['Reparatur', 'Wartung'].includes(ai.request_type) && !String(ai.device_info || '').trim()) {
  missing.push('Gerät und Hersteller (z. B. Typenschild), gern mit Foto');
}

const urgencyLabel = { emergency: 'Notfall', soon: 'zeitnah', plannable: 'planbar' }[ai.urgency] ?? 'planbar';

return [{
  json: {
    receivedAt: $now.setZone(settings.timezone || 'Europe/Berlin').toFormat('yyyy-MM-dd HH:mm'),
    senderEmail,
    subject: mail.subject ?? '',
    customerName: ai.customer_name ?? '',
    phone: ai.phone ?? '',
    address: [ai.street, [postcode, ai.city].filter(Boolean).join(' ')].filter(Boolean).join(', '),
    trade: ai.trade,
    requestType: ai.request_type,
    urgency: ai.urgency,
    urgencyLabel,
    deviceInfo: ai.device_info ?? '',
    propertyType: ai.property_type ?? 'unbekannt',
    preferredDates: ai.preferred_dates ?? '',
    summary: ai.summary ?? '',
    inServiceArea,
    missingInfo: missing,
    missingInfoText: missing.join('; '),
    isEmergency: ai.urgency === 'emergency',
    needsFollowUp: missing.length > 0 && ai.urgency !== 'emergency' && inServiceArea !== 'nein',
  }
}];
